import type { GameType, UnifiedCard, UnifiedSearchResponse } from './card-types'
import { pokemonApi, type PokemonCard } from './pokemon-api'
import { onePieceApi, type OnePieceCard } from './onepiece-api'

function fromPokemon(card: PokemonCard): UnifiedCard {
  return {
    id: card.id,
    gameType: 'pokemon',
    name: card.name,
    setName: card.set.name,
    imageSmall: card.images.small,
    imageLarge: card.images.large,
    rarity: card.rarity,
    marketPrice: pokemonApi.getMarketPrice(card),
  }
}

function fromOnePiece(card: OnePieceCard): UnifiedCard {
  return {
    id: card.card_image_id,
    gameType: 'onepiece',
    name: card.card_name,
    setName: card.set_name,
    imageSmall: card.card_image,
    rarity: card.rarity,
    marketPrice: card.market_price ?? null,
  }
}

export const cardApi = {
  async searchCards(query: string, gameType: GameType): Promise<UnifiedSearchResponse> {
    if (gameType === 'pokemon') {
      const response = await pokemonApi.searchCards(query)
      return {
        data: response.data.map(fromPokemon),
        totalCount: response.totalCount,
      }
    }

    const cards = await onePieceApi.searchCards(query)
    return {
      data: cards.map(fromOnePiece),
      totalCount: cards.length,
    }
  },

  async getRecentCards(gameType: GameType): Promise<UnifiedSearchResponse> {
    if (gameType === 'pokemon') {
      const response = await pokemonApi.getRecentCards()
      return {
        data: response.data.map(fromPokemon),
        totalCount: response.totalCount,
      }
    }

    const cards = await onePieceApi.getRecentCards()
    return {
      data: cards.map(fromOnePiece),
      totalCount: cards.length,
    }
  },

  async getCard(id: string, gameType: GameType): Promise<UnifiedCard> {
    if (gameType === 'pokemon') {
      const card = await pokemonApi.getCard(id)
      return fromPokemon(card)
    }

    const cards = await onePieceApi.getCard(id)
    if (cards.length === 0) throw new Error(`One Piece card not found: ${id}`)
    return fromOnePiece(cards[0])
  },
}
